const b = $json.body || {};
const t = b.tip_postare || '';
let profil = 'info';
if (t === 'D. Sedinta - propunere data (poll disponibilitate)') profil = 'sedinta_poll';
else if (['D. Sedinta - stabilire data','D. Sedinta extinsa','D. Discutii cu executia (solutii tehnice)','D. Sedinta CTS beneficiar','D. Sedinta de coordonare','D. Sedinta coordonare cantitati'].indexOf(t) >= 0) profil = 'sedinta_data';
else if (t === 'B. Vizita amplasament') profil = 'vizita';
else if (t.charAt(0) === 'F') profil = 'predare';
return [{ json: Object.assign({}, b, { profil: profil }) }];

const f = $json;
const nl = '\n';
const P = f.nume_proiect || '[proiect]';
let D = f.data || '[data]';
if (/^\d{4}-\d{2}-\d{2}$/.test(D)) { const dp = D.split('-'); D = dp[2] + '.' + dp[1] + '.' + dp[0]; }
const O = f.ora || '[ora]';
const S = f.sala ? (', in ' + f.sala) : '';
const OB = f.obiecte || '[obiecte]';
const L = f.link_sau_cale || '';
const DET = f.detalii || '';
const t = f.tip_postare || '';
const T = {};
T['A. Documentatie proiect pe Teams'] = 'Buna General,'+nl+nl+'In Teams (Files > 1.Tema proiectare.Caiet de sarcini) si pe server am incarcat documentatia de proiect: SF, caietul de sarcini, documentatia de lucru de la licitatie si documentul cu subiectele/ipotezele de la licitatie.'+nl+nl+'Va rog sa intocmiti o lista cu persoanele ce vor lucra pe acest proiect (cu adresa de mail) pentru a le adauga in Teams.'+(L?(nl+nl+'Cale: '+L):'')+nl+nl+'Multumesc. O zi buna!';
T['A. Lansare de proiect'] = 'Buna General,'+nl+nl+'Propun sa avem sedinta de lansare proiect pe '+D+' la ora '+O+S+'. Este in proces de completare Fisa de lansare proiect.'+nl+nl+'Va reamintesc activitatile de facut inainte de sedinta: analiza temei si completarea obiectelor in fisa (sheet 1), personalul cheie in C02, propunerea echipei pe specialitati de catre coordonatori, si eventuale intrebari pentru beneficiar in C03.'+nl+nl+'Daca data sau ora nu convine, anuntati cu Reply la aceasta postare.'+nl+nl+'Multumesc frumos!';
T['A. Management flux informational'] = 'Buna General, propun urmatorul flux de lucru privind managementul informatiei pe Teams:'+nl+nl+'- Documentele (dwg, pdf, word, excel) se incarca in folderele dedicate din canalele de proiect (General, 1.Birou Arhitectura, 2.Birou Structuri, 3.Birou Instalatii, 9.1 Drumuri).'+nl+'- Nu se lasa documente la liber, neincadrate in foldere clare.'+nl+'- Discutiile intre specialitati se fac in canalele de obiect, cu Reply la postarile existente.'+nl+'- Temele catre alte specialitati se incarca in canalul specialitatii destinatare; postarea de transmitere se face in canalul obiectului, cu Reply si link catre tema.'+nl+'- Cand o solutie se aplica pe mai multe obiecte, se mentioneaza toti proiectantii implicati.'+nl+nl+'Multumesc frumos. Spor!';
T['A. Date generale, antet, cartus, reguli'] = 'Buna General, in aceasta postare centralizam discutiile pe: date generale proiect, antet piese scrise, familie cartus si reguli de proiectare.'+nl+nl+'- Excel date generale proiect: General-Files-Organizare.'+nl+'- Antet piese scrise: General-Files-Organizare-Antet piese scrise.'+nl+'- Familie cartus: General-Files-Organizare-Familie cartus (+ export dwg).'+nl+'- Reguli generale si specifice: document setat ca Tab in canalul General.'+nl+nl+'Atentie: datele generale din piesele scrise trebuie sa fie identice cu cele din Excel; in cartus nu se scrie cu diacritice; scara planurilor DTAC/PTDE este 1:50 (exceptii: situatie, drumuri, detalii).'+(L?(nl+nl+'Link/cale: '+L):'')+nl+nl+'Multumesc frumos. Spor!';
T['B. Studii teren (Topo/Geo)'] = 'Buna General, in aceasta postare tinem centralizat discutiile pe Studiul Topo si Studiul Geotehnic.'+nl+nl+'Atasez tema pentru ridicarea topo si pentru studiul geo.'+(L?(nl+'Cale teme: '+L):'')+(DET?(nl+nl+DET):'')+nl+nl+'Multumesc frumos!';
T['B. Certificat de urbanism / Avize'] = 'Buna General, in aceasta postare centralizam discutiile pe Certificat de Urbanism si Avize obtinute.'+nl+nl+'Acestea se gasesc in Teams (02.Avize obtinute) si pe server.'+(L?(nl+'Cale: '+L):'')+(DET?(nl+nl+DET):'')+nl+nl+'Multumesc. Spor!';
T['B. Vizita amplasament'] = 'Buna General, pe '+D+' la ora '+O+' se va face o vizita in amplasament pentru preluarea informatiilor necesare proiectarii / predarea-primirea amplasamentului.'+nl+nl+'Transmiteti lista persoanelor care vor participa, pentru asigurarea accesului.'+nl+nl+'Pozele/filmarile se incarca in folderul dedicat de pe server. Am creat o pagina in OneNote pentru notarea informatiilor din santier. Atasez un Checklist de vizita (Elemente ridicare topo + Elemente etapa proiectare) - completati pe fiecare specialitate.'+(L?(nl+nl+'Cale/link: '+L):'')+nl+nl+'Multumesc frumos. Spor!';
T['C. Realizare proiect in ACC'] = 'Buna General, a fost creat in ACC proiectul, cu structura de foldere pe specialitati/obiecte, si s-a dat acces tuturor membrilor conform Fisei de Lansare.'+nl+nl+'Vom lucra in Revit '+(DET||'[versiune]')+' pentru toate specialitatile. Asigurati-va ca toti au versiunea corecta.'+nl+nl+'Atasez instructiunile de lucru in ACC (incarcare Revit, Design Collaboration, Model Coordination) si codificarea fisierelor.'+(L?(nl+'Link: '+L):'')+nl+nl+'Multumesc!';
T['C. Proiectant extern'] = 'Buna General, pentru lucrarea '+OB+' vom colabora cu un proiectant extern (Eticheta Teams).'+nl+nl+'Va rog ca toate conversatiile si informatiile legate de aceasta lucrare sa se realizeze in Teams si sa fie mentionat @eticheta. Pentru detalii sau transmiterea temei, dati tag proiectantului extern.'+nl+nl+'Multumesc!';
T['C. Workflow verificari'] = 'Buna General, completati astazi, pana la pranz, in fisierul Flux predari si verificari persoanele care se vor ocupa de verificari si implementari la verificarea de corectitudine din ACC, pe fiecare specialitate.'+nl+nl+'Anuntati-ma cand tabelul e completat, ca sa creez workflow-urile si sa adaug rolurile de verificator.'+(L?(nl+'Fisier: '+L):'')+nl+nl+'Multumesc frumos. Spor!';
T['D. Sedinta - propunere data (poll disponibilitate)'] = 'Buna General,'+nl+nl+'Pentru proiectul '+P+' trebuie sa stabilim data '+(f.obiecte?('sedintei pe '+OB):'unei sedinte')+'. Va rog sa propuneti, prin Reply la aceasta postare, ziua si intervalul orar in care sunteti disponibili.'+nl+nl+'Pe baza disponibilitatii voi verifica o sala si voi reveni cu confirmarea.'+nl+nl+'Multumesc!';
T['D. Sedinta - stabilire data'] = 'Buna General,'+nl+nl+'In urma disponibilitatilor, '+(f.obiecte?('sedinta pe '+OB):'sedinta')+' se stabileste pe '+D+' la ora '+O+S+'.'+nl+nl+'Va rog confirmati participarea. Daca ceva nu convine, anuntati cu Reply.'+nl+nl+'Multumesc!';
T['D. Sedinta extinsa'] = 'Buna General, pe '+D+' la ora '+O+S+' va avea loc Sedinta Extinsa pentru proiectul '+P+'.'+nl+nl+'Activitati de realizat inainte de sedinta (toate obiectele si specialitatile):'+nl+'- Studierea amanuntita a temei de proiectare.'+nl+'- Completarea Infobook (sheet Centralizator).'+nl+'- Completarea C.07_RFI (intrebari interne si catre beneficiar).'+nl+'- Intocmirea Checklist-urilor faza DTAC in ERP.'+(L?(nl+nl+'Infobook+RFI: '+L):'')+nl+nl+'Multumesc. Spor!';
T['D. Discutii cu executia (solutii tehnice)'] = 'Buna General, mai jos punctez subiectele de discutat cu colegii din executie pentru stabilirea solutiilor tehnice pe proiectul '+P+'.'+nl+nl+'Sedinta: '+D+', ora '+O+S+'.'+nl+nl+'Puneti cu Reply la aceasta postare toate subiectele de discutat, pe fiecare specialitate.'+(DET?(nl+nl+'Subiecte:'+nl+DET):'')+(L?(nl+nl+'Documente: '+L):'')+nl+nl+'Multumesc frumos. Spor!';
T['D. Sedinta CTS beneficiar'] = 'Buna General, pasul urmator este sa pregatim solutiile tehnice si intrebarile pe care le prezentam Beneficiarului.'+nl+nl+'Sedinta CTS va avea loc pe '+D+' la ora '+O+'.'+nl+nl+'Activitati de pregatit: citire/completare minuta sedinta extinsa, completare Infobook (coloana solutii proiectant), completare RFI, checklist-uri faza DTAC.'+nl+nl+'Vor participa persoanele nominalizate de coordonatori. Tinem informatia centralizata cu Reply la aceasta postare.'+nl+nl+'Multumesc frumos. Spor!';
T['D. Sedinta de coordonare'] = 'Buna General, pe '+D+' la ora '+O+S+' va avea loc sedinta de coordonare pe '+OB+'.'+nl+nl+'Pentru eficienta, analizati pe fiecare obiect si specialitate: stadiul proiectului, solutiile tehnice, necesitatile de la alte specialitati (teme) si blocantele/intrebarile care persista.'+nl+nl+'Ne vom uita pe documentatia incarcata in ACC.'+nl+nl+'Multumesc frumos. Spor!';
T['D. Sedinta coordonare cantitati'] = 'Buna General, pe '+D+' la ora '+O+S+' va avea loc sedinta de coordonare cantitati pe '+OB+'.'+(DET?(nl+nl+DET):'')+nl+nl+'Multumesc. Spor!';
T['E. Flux de lucru / verificari / reguli'] = 'Buna General, transmit mai jos pasii de urmat in procesul de proiectare:'+nl+'- Se prioritizeaza activitatile cu impact pe alte specialitati si documentatia pentru avize.'+nl+'- La verificari se confirma ca temele date catre alte specialitati sunt implementate; altfel, observatie in ERP + mesaj Teams.'+nl+'- Verificarile se fac a doua zi de la predarea unei faze.'+nl+'- Inainte de predare se citesc minutele sedintelor si se respecta solutiile agreate.'+nl+'- Se completeaza Infobook si RFI cu solutiile actualizate si intrebarile.'+nl+'- Dupa Approvals: Complete la task si start la faza urmatoare (eticheta Intrerupt daca lipsesc informatii).'+nl+'- Se activeaza alertele de modificare pe documentele comune din Teams/SharePoint.'+(DET?(nl+nl+DET):'')+nl+nl+'Multumesc. Spor!';
T['E. Actualizare documentatie in ACC'] = 'Buna General, conform minutei sedintei CTS, la fiecare doua saptamani asiguram incarcarea actualizata a documentatiei in ACC.'+nl+nl+'Va rog ca astazi pana la ora '+O+' sa incarcati in ACC documentatia in format editabil (dwg, Revit, word) pe fiecare obiect si specialitate, in folderele dedicate. Pentru Revit in BCP: setati Publish settings (planuri + 3D views) si realizati Publicarea.'+nl+nl+'Multumesc frumos si spor!';
T['E. Postare coordonare per obiect (DTAC/PTDE)'] = 'Buna General, deschid aceasta postare de coordonare pentru '+OB+' faza '+(DET||'[DTAC/PTDE + nr]')+'.'+nl+nl+'Aici centralizam conversatiile de coordonare Arhitectura-Rezistenta-Instalatii-Drumuri pentru acest obiect. Folositi Reply la aceasta postare pentru toate discutiile pe subiect.'+(L?(nl+nl+'Link: '+L):'')+nl+nl+'Multumesc. Spor!';
T['F. Predare DTAC/PSI/DTAD'] = 'Hello General, pe '+D+(f.ora?(' - ora '+O):'')+' trebuie sa avem gata de predare documentatia faza DTAC/PSI/DTAD.'+(L?(nl+nl+'Folder predare: '+L):'')+(DET?(nl+nl+DET):'')+nl+nl+'Confirmati citirea si anuntati orice risc fata de termen. Spor!';
T['F. Detach faza intermediara DTAC'] = 'Buna General, pentru faza intermediara DTAC trebuie sa realizam detach-urile in ACC pentru acces beneficiar.'+(L?(nl+nl+'Folder ACC: '+L):'')+(DET?(nl+nl+DET):'')+nl+nl+'Dati Reply cand ati pus plansele finale in folder. Multumesc!';
T['F. Predare documentatie PTDE'] = 'Hello General, pe '+D+(f.ora?(' - ora '+O):'')+' trebuie sa avem gata de predare in format fizic catre beneficiar documentatia PTDE'+(DET?(' ('+DET+')'):'')+'.'+(L?(nl+nl+'Folder predare: '+L):'')+nl+nl+'Toata documentatia trebuie: printata, indosariata, semnata si stampilata, verificata, opisata, in cutii, cu coperti. Documentatia PTDE trebuie si SCANATA!'+nl+nl+'Confirmati citirea si anuntati orice risc fata de termen. In BIM/ACC sa se regaseasca ultima varianta (cea printata) - confirmati prin Reply. Spor!';
T['F. Detach PT predat'] = 'Buna General, trebuie sa realizam detach-urile pentru PT-ul predat in ACC.'+(L?(nl+nl+'Folder ACC: '+L):'')+(DET?(nl+nl+DET):'')+nl+nl+'Confirmati prin Reply. Multumesc!';
T['F. Mesaj dupa predarea PTDE'] = 'Buna General, mesaj dupa predarea PTDE.'+(DET?(nl+nl+DET):'')+nl+nl+'Multumesc. Spor!';
T['F. Finalizare cantitati'] = 'Buna General, finalizare cantitati.'+(DET?(nl+nl+DET):'')+nl+nl+'Multumesc. Spor!';
T['F. Realizare nota justificativa'] = 'Buna General, realizare nota justificativa.'+(DET?(nl+nl+DET):'')+nl+nl+'Multumesc. Spor!';
T['F. Predare DALI (1 exemplar)'] = 'Buna General, Important! Pe '+D+' (pana la finalul zilei) trebuie sa avem gata de predare in format fizic catre beneficiar documentatia DALI - 1 exemplar.'+(L?(nl+nl+'Folder predare: '+L):'')+nl+nl+'Toata documentatia: printata, indosariata, semnata si stampilata de proiectanti. Incarcati in ACC detach-urile pentru acces beneficiar.'+nl+nl+'Dati Reply cand ati pus plansele finale in folder si asigurati-va ca ati completat piesele scrise pe fiecare specialitate. Multumesc!';
T['F. Lectii invatate'] = 'Buna General, la finalul proiectului '+P+' completati formularul de Lectii Invatate.'+(DET?(nl+nl+DET):'')+nl+nl+'Multumesc. Spor!';
const msg = T[t] || ('[Sablon indisponibil pentru: '+t+']'+nl+DET);
return [{ json: { message: msg, tip: t } }];

const ctx = $('Determina profil').item.json;
const f = ctx;
const msg = $('Compune mesajul din template').item.json.message || '';
const iso = (f.data || '').substring(0, 10);
const start = iso + 'T' + (f.ora || '00:00') + ':00';
const end = iso + 'T' + (f.ora_sfarsit || f.ora || '00:00') + ':00';
const members = ($('Obtine Membri Echipa').item.json.value) || [];
const participants = members.filter(function(m){ return m.email; }).map(function(m){ return m.email; });
const title = (f.nume_proiect ? f.nume_proiect + ' - ' : '') + (ctx.tip_postare || '').replace(/^[A-F]\. /, '');
return [{ json: { meetingTitle: title, confirmedDateTime: start, confirmedEndDateTime: end, participants: participants, agendaText: msg, onlineMeeting: true } }];

const composed = $('Compune mesajul din template').item.json.message || '';
const tip = $('Compune mesajul din template').item.json.tip || '';
const webLink = $json.webLink || '';
const message = composed + (webLink ? ('\n\n\ud83d\udd17 Link sedinta (calendar): ' + webLink) : '');
return [{ json: { message: message, tip: tip } }];

const b = $('Webhook Trimite').item.json.body || {};
const msg = b.message || '';
const t = b.tip_postare || '';
const teamId = b.teamId || '';
const channelId = b.channelId || '';
const channelName = b.channelName || 'General';
const uploadedFiles = $json.uploadedFiles || [];
const title = t.replace(/^[A-F]\. /, '');

let attachmentsHtml = '';
const graphAttachments = uploadedFiles.map(function(f, idx){
  const attId = 'att' + idx;
  attachmentsHtml += '<attachment id="' + attId + '"></attachment>';
  return { id: attId, contentType: 'reference', contentUrl: f.webUrl, name: f.filename };
});

const bodyContent = '<at id="0">' + channelName + '</at><br><br>' + msg.split('\n').join('<br>') + (attachmentsHtml ? ('<br><br>' + attachmentsHtml) : '');
const graphBody = { subject: title, body: { contentType: 'html', content: bodyContent }, mentions: [ { id: 0, mentionText: channelName, mentioned: { conversation: { id: channelId, displayName: channelName, conversationIdentityType: 'channel' } } } ], attachments: graphAttachments };
const url = 'https://graph.microsoft.com/v1.0/teams/' + teamId + '/channels/' + channelId + '/messages';
return [{ json: { url: url, graphBody: graphBody } }];

const teamId = $('Cauta Echipa Dupa Cod').item.json.value[0].id;
const channels = ($json.value || []).map(function(c){ return { id: c.id, displayName: c.displayName }; });
return [{ json: { teamId: teamId, channels: channels } }];

const folder = $json;
const driveId = folder.parentReference.driveId;
const folderId = folder.id;
const attachments = $('Webhook Trimite').item.json.body.attachments || [];
return attachments.map(function(a){
  return {
    json: { filename: a.filename, mimeType: a.mimeType || 'application/octet-stream', driveId: driveId, folderId: folderId },
    binary: { data: { data: a.base64, mimeType: a.mimeType || 'application/octet-stream', fileName: a.filename } }
  };
});

const items = $input.all();
const files = items.map(function(it){
  return { id: it.json.id, webUrl: it.json.webUrl, filename: it.json.name || '' };
});
return [{ json: { uploadedFiles: files } }];
